package store.cadera.cdrjobs.command;
import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.JobType;import store.cadera.cdrjobs.service.ProgressionService;import store.cadera.cdrjobs.util.Colors;import java.util.*;
public final class AdminCommand implements CommandExecutor,TabCompleter{private final CdrJobsPlugin plugin;private final Database db;private final ProfessionStore store;private final ProgressionService progression;public AdminCommand(CdrJobsPlugin p,Database d,ProfessionStore s,ProgressionService pr){plugin=p;db=d;store=s;progression=pr;}@Override public boolean onCommand(@NotNull CommandSender sender,@NotNull Command command,@NotNull String label,@NotNull String[]args){if(!sender.hasPermission("cdrjobs.admin")){sender.sendMessage(Colors.color(plugin.prefix()+plugin.message("no-permission")));return true;}if(args.length==1&&args[0].equalsIgnoreCase("reload")){plugin.reloadPluginFiles();sender.sendMessage(Colors.color(plugin.prefix()+plugin.message("admin-reload")));return true;}if(args.length==1&&args[0].equalsIgnoreCase("diagnose")){sender.sendMessage("§3CdrJobs Diagnostics");sender.sendMessage("§fVersion: §b"+plugin.getPluginMeta().getVersion());sender.sendMessage("§fSchema: §b"+store.getSchemaVersion());sender.sendMessage("§fPaper: §b"+Bukkit.getMinecraftVersion());sender.sendMessage("§fPlaceholderAPI: §b"+(Bukkit.getPluginManager().isPluginEnabled("PlaceholderAPI")?"ENABLED":"NOT INSTALLED"));sender.sendMessage("§fProfessions: §b5/5 enabled in core");return true;}if(args.length>=2&&args[0].equalsIgnoreCase("reset")){Player t=Bukkit.getPlayerExact(args[1]);if(t==null){sender.sendMessage("§cPlayer harus online.");return true;}db.resetPlayer(t.getUniqueId());store.resetPlayer(t.getUniqueId());sender.sendMessage("§aCdrJobs data reset: "+t.getName());return true;}if(args.length>=3&&(args[0].equalsIgnoreCase("addxp")||args[0].equalsIgnoreCase("setlevel"))){Player t=Bukkit.getPlayerExact(args[1]);if(t==null){sender.sendMessage("§cPlayer harus online.");return true;}JobType job=JobType.MINER;String val=args[2];if(args.length>=4){try{job=JobType.valueOf(args[2].toUpperCase());val=args[3];}catch(Exception e){sender.sendMessage("§cJob tidak valid.");return true;}}try{if(args[0].equalsIgnoreCase("addxp")){long n=Long.parseLong(val);progression.addXp(t,job,n);sender.sendMessage("§aAdded "+n+" "+job+" XP.");}else{progression.setLevel(t,job,Integer.parseInt(val));sender.sendMessage("§a"+job+" level updated.");}}catch(NumberFormatException e){sender.sendMessage("§cNilai harus angka.");}return true;}sender.sendMessage("§b/cdrjobsadmin diagnose | reload | reset | addxp | setlevel");return true;}@Override public @Nullable List<String>onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String a,@NotNull String[]args){if(args.length==1)return List.of("diagnose","reload","addxp","setlevel","reset");if(args.length==2&&!args[0].equalsIgnoreCase("reload")&&!args[0].equalsIgnoreCase("diagnose")){List<String>n=new ArrayList<>();Bukkit.getOnlinePlayers().forEach(p->n.add(p.getName()));return n;}if(args.length==3&&(args[0].equalsIgnoreCase("addxp")||args[0].equalsIgnoreCase("setlevel")))return Arrays.stream(JobType.values()).map(x->x.name().toLowerCase()).toList();return List.of();}}
